mapper.select:


    inner join sys_user u on u.user_name = tputawayrule.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tputawayrule.del_flag = '0'
     and tputawayrule.rule_no = #{ruleNo}
     and tputawayrule.rule_desc = #{ruleDesc}
     and tputawayrule.status = #{status}


${params.dataScope}
